@js:(function(){
  // 🅴ExHentai 发现列表：13 项分类，{{page}} 原生翻页（站点自身空列表自然终止，不写死上限）
  // ⭐关注 = 实时读 mytags watched 标签拼 OR 搜索(~"tag$")，缓存命中零请求，失败回退 /watched
  function g(k,def){var v='';try{v=String(source.get(k))}catch(e){v=''}if(v==='null'||v==='undefined'||v==='NaN'||v==='')v=def||'';return v}
  var d=g('ehHost','https://exhentai.org').replace(/\/+$/,'');
  if(d.indexOf('http')!==0)d='https://exhentai.org';
  var UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36';
  var C=[
    ['🆕 最新（全部）', ''],
    ['📈 热门', 'popular'],
    ['⭐ 关注', 'watched'],
    ['📚 同人志 Doujinshi', 'f_cats=1021'],
    ['📖 漫画 Manga', 'f_cats=1019'],
    ['🎨 画师CG ArtistCG', 'f_cats=1015'],
    ['🎮 游戏CG GameCG', 'f_cats=1007'],
    ['🖼 图集 ImageSet', 'f_cats=991'],
    ['👗 Cosplay', 'f_cats=959'],
    ['🌏 亚洲 AsianPorn', 'f_cats=895'],
    ['🚫 全年龄 Non-H', 'f_cats=767'],
    ['🌍 欧美 Western', 'f_cats=511'],
    ['📦 杂项 Misc', 'f_cats=1022'],
  ];
  function watchedQuery(){
    try{
      var tags=[],cr='';try{cr=String(source.get('ehTagCache')||'')}catch(e){}
      if(cr){var c=JSON.parse(cr);for(var k in (c.tags||{}))tags.push(k);}
      if(!tags.length){
        var raw=g('ehCookie',''),ig=g('ehIgneous','')||'';
        if(ig==='mystery'||ig==='null'||ig==='undefined'||ig==='0')ig='';
        var ck='igneous=';
        if(raw.indexOf('ipb_member_id=')>=0&&raw.indexOf('ipb_pass_hash=')>=0){
          var ps=raw.split(';'),keep=[],seen={},OK=['ipb_member_id','ipb_pass_hash','inline_set'];
          for(var i=0;i<ps.length;i++){var p=ps[i].trim(),eq=p.indexOf('=');if(eq<1)continue;var kk=p.substring(0,eq).trim(),vv=p.substring(eq+1).trim();if(OK.indexOf(kk)<0||seen[kk]||vv==='')continue;seen[kk]=1;keep.push(kk+'='+vv)}
          if(keep.join(';').indexOf('inline_set=')<0)keep.push('inline_set=dm_l');
          keep.push('igneous='+ig);ck=keep.join('; ');
        }
        var H0={'User-Agent':UA,'Cookie':ck,'Referer':d+'/'};
        var mb=String(java.ajax(d+'/mytags,'+JSON.stringify(H0))||'');
        if(mb.length>3000&&mb.indexOf('usertag_')>=0&&!/temporarily banned|Sad Panda/i.test(mb.slice(0,300))){
          var re=/id="tagwatch_(\d+)"[^>]*checked/g,m;
          while((m=re.exec(mb))!==null){var pm=new RegExp('id="tagpreview_'+m[1]+'"[^>]*title="([^"]*)"').exec(mb);if(pm)tags.push(pm[1]);}
        }
      }
      if(!tags.length)return '';
      if(tags.length>26)tags=tags.slice(0,26);
      var q=[];for(var j=0;j<tags.length;j++)q.push('~"'+tags[j]+'$"');
      return q.join(' ');
    }catch(e){return ''}
  }
  var out=[];
  for(var i=0;i<C.length;i++){
    var name=C[i][0],q=C[i][1],url;
    if(q===''){url=d+'/?page={{page}}';}
    else if(q==='popular'){url=d+'/popular?page={{page}}';}
    else if(q==='watched'){
      var wq=watchedQuery();
      url=wq?(d+'/?f_search='+encodeURIComponent(wq)+'&page={{page}}'):(d+'/watched?page={{page}}');
    } else {url=d+'/?'+q+'&page={{page}}';}
    out.push(name+'::'+url);
  }
  // ==== 收藏夹：抓 favorites.php 的夹名单，生成各收藏夹发现入口 ====
  try {
    var fh = String(java.ajax(d + '/favorites.php,' + JSON.stringify({'User-Agent':UA,'Referer':d+'/'})) || '');
    if (fh.length > 3000 && fh.indexOf('class="fp"') >= 0 && !/Sad Panda|temporarily banned/i.test(fh.slice(0,300))) {
      var fre = /<div class="fp"[^>]*favcat=(\d)[^>]*>([\s\S]*?)(?=<div class="fp"|id="favtable"|$)/g, fm;
      var favs = [];
      while ((fm = fre.exec(fh)) !== null) {
        var tn = /title="([^"]*)"/.exec(fm[2]);
        var cn = /font-weight:bold;[^>]*>([\d,]+)</.exec(fm[2]);
        var fname = tn ? tn[1] : ('收藏夹'+fm[1]);
        favs.push([fm[1], fname, cn?cn[1]:'']);
      }
      if (favs.length) {
        out.push('━━━━ 📁 我的收藏夹 ━━━━::' + d + '/favorites.php');  // 分组标题项(无实际列表)
        for (var fi=0; fi<favs.length; fi++) {
          var furl = d + '/favorites.php?favcat=' + favs[fi][0] + '&page={{page}}';
          out.push('📁 ' + favs[fi][1] + ' (' + favs[fi][2] + ')::' + furl);
        }
      }
    }
  } catch(eFav) {}
  // ==== 把每个 ::URL 包装成「URL 选项 js」，用 page 算出真实 next 游标（站点不认页码）====
  function navWrap(u, k) {
    if (!u || u.indexOf('{{page}}') < 0) return u;   // 分组标题项无需翻页
    var base = u.split('{{page}}')[0].replace(/[?&]page=$/, '').replace(/[?&]$/, '');
    // ★★URL 选项 js 会被 UI 内嵌到 <script> 执行，源码里禁止出现 < > 字符（HTML 解析器会吞掉它们及中间内容）
    // 等价改写：P<=1 → P===1；i<0 → i===-1；>=0 → !==-1；arr.length<P-1 → !arr[P-2]
    var js = "(function(){var B=" + JSON.stringify(base) + ",K=" + JSON.stringify(k) +
      ",P=(typeof page==='number'?page:parseInt(page,10)||1);if(P===1)return B;" +
      "function nx(h){var i=h.indexOf('next=');if(i===-1)return '';var m=String(h).substring(i+5,i+30).match(/^([0-9]+)/);return m?m[1]:'';}" +
      "var ck='ehNav_'+K,arr=[];try{var o=JSON.parse(String(source.get(ck)||'')||'{}');if(o.b===B){if(o.a)arr=o.a;}}catch(e){}" +
      "var cur=arr.length?B+(B.indexOf('?')!==-1?'&':'?')+'next='+arr[arr.length-1]:B;" +
      "while(!arr[P-2]){var h=String(java.ajax(cur)||'');var n=nx(h);if(!n)break;arr.push(n);cur=B+(B.indexOf('?')!==-1?'&':'?')+'next='+n;}" +
      "try{source.put(ck,JSON.stringify({b:B,a:arr}));}catch(e2){}" +
      "if(!arr[P-2])return B;return B+(B.indexOf('?')!==-1?'&':'?')+'next='+arr[P-2];})()";
    return base + ',{"js":' + JSON.stringify(js) + '}';
  }
  var wrapped = [];
  for (var wi=0; wi<out.length; wi++) {
    var sep = out[wi].indexOf('::');
    if (sep < 0) { wrapped.push(out[wi]); continue; }
    var ttl = out[wi].substring(0, sep), uu = out[wi].substring(sep+2);
    wrapped.push(ttl + '::' + navWrap(uu, 'ex'+wi));
  }
  // ★改为 JSON 数组返回：走 exploreKinds() 的 GSON 分支，彻底避开文本路径的分隔符切割
  var rows = [];
  for (var ri=0; ri<wrapped.length; ri++) {
    var sp = wrapped[ri].indexOf('::');
    if (sp < 0) continue;
    rows.push({title: wrapped[ri].substring(0, sp), url: wrapped[ri].substring(sp+2)});
  }
  return JSON.stringify(rows);
})()

