// ==================== loginCheckJs：绕开 OkHttp/CookieJar 白屏（261107 定案） ====================
// 源码 Rss.getArticles / Rss.getContentAwait:
//   analyzeUrl.getStrResponseAwait().let { analyzeUrl.evalJS(checkJs, it) as StrResponse }
//   bindings["result"] = 原始 StrResponse；这里必须返回 StrResponse。
// ★ 双栈对照实锤：OkHttp+CookieJar 栈对 exhentai HTML 恒 0B（igneous=mystery 白屏），
//   java.ajax(jsoup 纯净栈 + 只发 member/pass 两项) 恒 60KB+ 正常 HTML。
//   ⇒ 空响应时用 ajax 重取，new StrResponse(url, fresh) 替换。
// ★ Cookie 来源：仅面板变量 ehCookie；为空时不重取（明确提示用户粘贴），绝不硬编码测试账号。
(function (r) {
  var UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36';
  // ★261114 v5.2：绝不硬编码账号凭据/igneous；没配 ehCookie 就保持原响应（由 header 层提示）
  function g(k) {
    var v = '';
    try { v = String(source.get(k)); } catch (e) { v = ''; }
    if (v === 'null' || v === 'undefined' || v === 'NaN' || v === '') v = '';
    return v;
  }
  // ★261114 v5.1：只发两项 + inline_set + 显式合法 igneous（覆盖 CookieStore 残留 mystery）
  function cookie2() {
    var raw = g('ehCookie');
    if (raw.indexOf('ipb_member_id=') < 0 || raw.indexOf('ipb_pass_hash=') < 0) return '';
    var parts = raw.split(';'), keep = [], seen = {}, OK = ['ipb_member_id', 'ipb_pass_hash', 'inline_set'];
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].trim(), eq = p.indexOf('=');
      if (eq < 1) continue;
      var k = p.substring(0, eq).trim(), v = p.substring(eq + 1).trim();
      if (OK.indexOf(k) < 0 || seen[k] || v === '') continue;   // 忽略 igneous，下面统一补
      seen[k] = 1; keep.push(k + '=' + v);
    }
    if (keep.join(';').indexOf('inline_set=') < 0) keep.push('inline_set=dm_l');
    var ig = g('ehIgneous') || '';
    if (ig === 'mystery' || ig === 'undefined' || ig === 'null' || ig === '0') ig = '';
    keep.push('igneous=' + ig);   // 空值占位：覆盖库内 mystery + 让站方重签该账号的值
    return keep.join('; ');
  }
  var url = '';
  try { url = String(r.url()); } catch (e) { return r; }
  var body = '';
  try { body = String(r.body()); } catch (e) { body = ''; }
  if (body === 'null' || body === 'undefined') body = '';
  // 已经正常就原样返回，避免每个请求都二次取
  if (body.length > 5000 && body.indexOf('<') === 0 && !/temporarily banned|excessive request/i.test(body.slice(0, 400))) return r;
  if (!url || url.indexOf('hentai.org') < 0) return r;
  var fresh = '';
  var CK2 = cookie2();
  if (!CK2) return r;   // ★ 未配置用户 Cookie ⇒ 不重取（否则会用空 Cookie 打到 Sad Panda）
  try {
    var H = JSON.stringify({ 'User-Agent': UA, 'Cookie': CK2, 'Referer': 'https://exhentai.org/' });
    // ★261114 v6.9 不再带 dnsIp（直连残留清除，对照实验实锤带IP池必吃banned页）
    var HO = JSON.parse(H);
    fresh = String(java.ajax(url + ',' + JSON.stringify(HO)));
  } catch (e) { fresh = ''; }
  if (fresh.length > 1000 && fresh.indexOf('<') === 0) {
    try {
      var nr = new Packages.io.legado.app.help.http.StrResponse(url, fresh);
      return nr;
    } catch (e2) { return r; }
  }
  return r;
})(result)

