// ==================== ExHentai 订阅源 · 登录/凭据/代理面板 (v2) ====================
// ★261107 修复要点（三组对照实验实锤）：
//  ① V1 loginUi 的输入框值由 handleButtonClick 绑成 `result`（getLoginData 的 Map），
//     不是 source.put ⇒ 旧版 action 读 source.get('ehCookieInput') 恒空（用户填了没保存）。
//     现统一 EH_input(key) 从 result 读，兼容 login() 传参与 source.get 兜底。
//  ② 只发 ipb_member_id + ipb_pass_hash 两项：带旧 igneous / CookieJar merge 的
//     igneous=mystery ⇒ 站方 0B 白屏；不带则服务器重新签发有效 igneous(30天)，HTML 正常。
//  ③ java.ajax 走纯净栈能拿 67KB HTML，java.connect(OkHttp+CookieJar) 恒 0B
//     ⇒ 检测与自愈一律用 ajax；订阅源正式请求靠 loginCheckJs 替换响应体（见 build.py）。
var EH_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36';
var EH_OK = ['ipb_member_id', 'ipb_pass_hash', 'inline_set'];
// ★261114 v5.2：igneous 是账号绑定值，绝不硬编码；空值占位让站方重签该账号自己的值

function EH_toast(t) {
  try { java.longToast(String(t)); } catch (e) { try { java.toast(String(t)); } catch (e2) {} }
}
function EH_gv(k, def) {
  var v = '';
  try { v = String(source.get(k)); } catch (e) { v = ''; }
  if (v === 'null' || v === 'undefined' || v === 'NaN' || v === '') v = def || '';
  return v;
}
function EH_set(k, v) { try { source.put(k, v); } catch (e) {} }
// ★ 从 V1 面板绑定的 result(Map) 读输入框；三通道兜底
function EH_input(k) {
  var v = '';
  try {
    if (typeof result !== 'undefined' && result != null) {
      if (typeof result.get === 'function') { try { v = String(result.get(k)); } catch (e0) {} }
      if (!v || v === 'null' || v === 'undefined') { try { v = String(result[k]); } catch (e1) {} }
    }
  } catch (e) {}
  if (!v || v === 'null' || v === 'undefined' || v === 'NaN') v = EH_gv(k, '');
  return v;
}
function EH_host() {
  var d = EH_gv('ehHost', 'https://exhentai.org').replace(/\/+$/, '');
  if (d.indexOf('http') !== 0) d = 'https://' + d;
  return d;
}
// 与 header.js 完全同逻辑：只保留两项 + inline_set，剔除 igneous/yay/sk/star
function EH_cookie(raw) {
  var parts = String(raw || '').split(';'), keep = [], seen = {}, i, p, eq, k, v;
  for (i = 0; i < parts.length; i++) {
    p = parts[i].trim(); eq = p.indexOf('=');
    if (eq < 1) continue;
    k = p.substring(0, eq).trim(); v = p.substring(eq + 1).trim();
    if (EH_OK.indexOf(k) < 0 || seen[k] || v === '') continue;
    seen[k] = 1; keep.push(k + '=' + v);
  }
  if (keep.join(';').indexOf('inline_set=') < 0) keep.push('inline_set=dm_l');
  var ig = EH_gv('ehIgneous', '') || '';
  if (ig === 'mystery' || ig === 'null' || ig === 'undefined' || ig === '0') ig = '';
  var cleaned = [];
  for (i = 0; i < keep.length; i++) if (keep[i].indexOf('igneous=') !== 0) cleaned.push(keep[i]);
  cleaned.push('igneous=' + ig);
  return cleaned.join('; ');
}
// 构造 java.ajax 的 URL 选项串（纯净栈，不装 CookieJar）
function EH_ajaxUrl(path) {
  var h = { 'User-Agent': EH_UA, 'Cookie': EH_cookie(EH_gv('ehCookie', '')), 'Referer': 'https://exhentai.org/' };
  return EH_host() + path + ',{"headers":' + JSON.stringify(h) + '}';
}

// ---- 💾 保存 Cookie（从 result 读粘贴框） ----
function EH_applyCookie() {
  var raw = EH_input('ehCookieInput');
  if (!raw) { EH_toast('⚠ 请先在上方框里粘贴 Cookie，再点保存'); return; }
  var s = String(raw).replace(/\r/g, '').replace(/\n/g, ' ').trim();
  // 解析：接受 "k: v" 多行 / 分号串 / document.cookie
  var parts = s.replace(/:\s*/g, '=').split(/[;\n]+/), out = [], seen = {}, gotMember = false, gotPass = false;
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i].trim(), eq = p.indexOf('=');
    if (eq < 1) continue;
    var k = p.substring(0, eq).trim(), v = p.substring(eq + 1).trim();
    if (seen[k] || v === '' || v === 'undefined' || v === 'null') continue;
    // ★261114 v5.1：粘贴串里的 igneous=mystery 绝不入库
    if (k === 'igneous') continue;
    if (k === 'ipb_member_id') gotMember = true;
    if (k === 'ipb_pass_hash') gotPass = true;
    seen[k] = 1; out.push(k + '=' + v);
  }
  if (!gotMember || !gotPass) {
    EH_set('ehCookie', s);
    EH_toast('⚠ 未同时识别到 ipb_member_id 与 ipb_pass_hash，已原样保存；请检查格式');
  } else {
    EH_set('ehCookie', out.join('; '));
    // ★ 关键：把 igneous 等容易失效的键从「发送串」里剔除（header 只发两项让站方重签）
    EH_set('ehCookieInput', out.join('; '));
    EH_toast('✅ 已保存（' + out.length + ' 项，已剔除 igneous 脏值）。★请求时用面板「🔄 刷新 igneous」维护的合法值，不再反复白屏');
  }
  EH_refresh();
}
function EH_applyProxy() {
  var p = EH_input('ehProxyInput').trim();
  if (!p) { EH_set('ehProxy', ''); EH_toast('✅ 已清空代理（直连/VPN 全局模式）'); EH_refresh(); return; }
  if (!/^(https?|socks5|socks4):\/\//i.test(p)) p = 'http://' + p;
  EH_set('ehProxy', p);
  EH_toast('✅ 代理已设为 ' + p + '；请点「🔍检测连通」验证');
  EH_refresh();
}
function EH_clearCookie() {
  EH_set('ehCookie', ''); EH_set('ehCookieInput', '');
  EH_toast('✅ 已清除面板 Cookie（游客模式）');
  EH_refresh();
}
function EH_switchHost(n) {
  var d = (Number(n) === 1) ? 'https://exhentai.org' : 'https://e-hentai.org';
  EH_set('ehHost', d);
  EH_toast('✅ 已切换到 ' + d + '；重新进入订阅/发现页生效');
  EH_refresh();
}
// ---- 🧹 清域 Cookie + 🩺 一键自愈（核心修复） ----
function EH_purge() {
  try { cookie.removeCookie('https://exhentai.org/'); } catch (e) {}
  try { cookie.removeCookie('https://e-hentai.org/'); } catch (e) {}
  EH_toast('✅ 已清 App 内 hentai 域 Cookie（含失效的 igneous=mystery / yay / sk）');
}
function EH_heal() {
  EH_toast('🩺 开始自愈：清域 Cookie → 只发两项重新触发站方签发 igneous…');
