// 协议实锤（ExH login 用户脚本 / Let's panda / xeHentai core.py 三方一致）：
//   POST https://forums.e-hentai.org/index.php?act=Login&CODE=01
//   Content-Type: application/x-www-form-urlencoded
//   body: referer=...&b=&bt=&UserName=<用户名>&PassWord=<密码>&CookieDate=1
//   成功判据：响应含 "You are now logged in as"；Set-Cookie 给 ipb_member_id / ipb_pass_hash
// ★ 但本环境 forums 域被 Cloudflare Turnstile 挡死（GET/POST 一律 403 cf-mitigated: challenge，
//   换 UA 无效）⇒ 纯 HTTP 自动登录不可行。正解 = java.startBrowserAwait 打开内置浏览器，
//   用户手动过盾 + 登录，回来后从 CookieStore 抽取两项写回 ehCookie。
// ★ Cookie 按二级域归并：forums.e-hentai.org 与 e-hentai.org 同域共享，
//   但 exhentai.org 是另一个二级域 ⇒ 必须显式 cookie.setCookie 复制过去。
var EH_FORUM = 'https://forums.e-hentai.org/index.php?act=Login&CODE=00';
var EH_LOGIN_POST = 'https://forums.e-hentai.org/index.php?act=Login&CODE=01';

function EH_creds() {
  var u = EH_input('ehUser'), p = EH_input('ehPass');
  return { u: String(u || '').trim(), p: String(p || '').trim() };
}
// 从任意 Cookie 串里抽两项（含 URL 编码/引号容错）
function EH_extract2(raw) {
  var s = String(raw || '').replace(/\r/g, '').replace(/\n/g, ' ');
  var parts = s.split(';'), keep = {}, i, q, eq, k, v;
  for (i = 0; i < parts.length; i++) {
    q = parts[i].trim(); eq = q.indexOf('=');
    if (eq < 1) continue;
    k = q.substring(0, eq).trim().replace(/^["']|["']$/g, '');
    v = q.substring(eq + 1).trim().replace(/^["']|["']$/g, '');
    if ((k === 'ipb_member_id' || k === 'ipb_pass_hash') && v && !keep[k]) keep[k] = v;
  }
  return keep;
}
// 把抽到的两项写进：① 源变量 ehCookie ② exhentai.org 域持久 Cookie
function EH_commitCreds(keep, from) {
  if (!keep.ipb_member_id || !keep.ipb_pass_hash) return false;
  var two = 'ipb_member_id=' + keep.ipb_member_id + '; ipb_pass_hash=' + keep.ipb_pass_hash + '; inline_set=dm_l';
  EH_set('ehCookie', two);
  EH_set('ehCookieInput', two);
  try { cookie.setCookie('https://exhentai.org/', two); } catch (e) {}
  // 清掉可能残留的 mystery，让站方重新签发
  try { cookie.removeCookie('https://exhentai.org/'); } catch (e) {}
  try { cookie.setCookie('https://exhentai.org/', two); } catch (e) {}
  EH_toast('✅ ' + from + ' 登录成功！已取得 ipb_member_id=' + keep.ipb_member_id +
           '，Cookie 已写入源变量与里站域。请点「🔍 检测连通」验证，再重进订阅页');
  EH_refresh();
  return true;
}
// 通道 A：直接 POST（出口没被 CF 挡时最快）
function EH_tryPost(c) {
  var body = 'referer=https://forums.e-hentai.org/index.php?&b=&bt=&UserName=' +
             encodeURIComponent(c.u) + '&PassWord=' + encodeURIComponent(c.p) + '&CookieDate=1';
  var opt = '{"method":"POST","body":' + JSON.stringify(body) +
            ',"headers":{"User-Agent":' + JSON.stringify(EH_UA) +
            ',"Content-Type":"application/x-www-form-urlencoded"' +
            ',"Referer":"https://forums.e-hentai.org/index.php?act=Login&CODE=00"}}';
  var r, b = '';
  try {
    r = java.connect(EH_LOGIN_POST + ',' + opt, '', 20000);
    b = String(r.body());
  } catch (e) { return { ok: false, reason: 'POST异常 ' + String(e).slice(0, 50) }; }
  if (/Just a moment|cf-mitigated|challenge|Checking your browser/i.test(b)) {
    return { ok: false, reason: 'Cloudflare 挑战页（需内置浏览器过盾）' };
  }
  if (/You are now logged in as|Logged in as|logout|Log Out/i.test(b)) {
    // 从响应头 Set-Cookie 或 CookieStore 取
    var raw = '';
    try { raw = String(r.headers()); } catch (e) {}
    if (!raw) { try { raw = String(cookie.getCookie('https://forums.e-hentai.org/')); } catch (e2) {} }
    var k = EH_extract2(raw);
    if (!k.ipb_member_id) { try { k = EH_extract2(cookie.getCookie('https://forums.e-hentai.org/')); } catch (e3) {} }
    if (k.ipb_member_id && k.ipb_pass_hash) return { ok: true, keep: k };
    return { ok: false, reason: '登录成功但未读到 Cookie（检查 CookieJar）' };
  }
  return { ok: false, reason: '账号密码错误 / 需验证码 / 未识别响应（' + b.length + 'B）' };
}
// 通道 B：内置浏览器（过 CF + 手动登录，用户填完点页面里的登录即可）
function EH_browserLogin() {
  EH_toast('🌐 正在打开论坛登录页…请在内置浏览器里完成 Cloudflare 验证并登录账号，登录后返回本面板再点「🔄 读取登录 Cookie」');
  try {
    var r = java.startBrowserAwait(EH_FORUM, 'E-Hentai 论坛登录（过CF验证并登录）', false);
    EH_toast('🌐 浏览器已返回（' + String(r.body()).length + 'B）。请点「🔄 读取登录 Cookie」把登录态写进本源');
  } catch (e) {
