  }
}
// 通道 C：从浏览器登录后的 CookieStore 读取并写回
function EH_readBrowserCookie() {
  var raws = [
    'https://forums.e-hentai.org/', 'https://e-hentai.org/', 'https://exhentai.org/'
  ], i, k = {};
  for (i = 0; i < raws.length; i++) {
    try {
      var s = String(cookie.getCookie(raws[i]));
      var q = EH_extract2(s);
      if (q.ipb_member_id && !k.ipb_member_id) k.ipb_member_id = q.ipb_member_id;
      if (q.ipb_pass_hash && !k.ipb_pass_hash) k.ipb_pass_hash = q.ipb_pass_hash;
    } catch (e) {}
  }
  if (EH_commitCreds(k, '浏览器登录')) return;
  EH_toast('⚠ 未读到 ipb_member_id / ipb_pass_hash。请确认已在内置浏览器里登录成功（页面显示用户名），或改用下方「粘贴 Cookie」通道');
}
