      if (u1) { hdMap[hdLinks[a]] = u1; okN++; }
      else { noImgN++; missList.push(a); }
    }

    // ② 表站漏掉的 → 里站 + Cookie 补齐（逐条，不整批重试）
    if (missList.length) {
      mode += '+里站补' + missList.length;
      var retryUrls = [], retryIdx = [];
      for (var k = 0; k < missList.length; k++) {
        retryUrls.push(hdLinks[missList[k]]);
        retryIdx.push(missList[k]);
      }
      var exBodies = runBatch(retryUrls, true);
      for (var k2 = 0; k2 < retryUrls.length; k2++) {
        var exKey = retryUrls[k2].split(',{')[0];
        var b2 = exBodies[exKey] || exBodies['__IDX__' + k2] || '';
        if (!b2) continue;
        var u2 = hdPick(b2);
        if (u2) {
          hdMap[hdLinks[retryIdx[k2]]] = u2;
          okN++;
          noImgN = 0; emptyN = Math.max(0, emptyN - 1);
        }
      }
    }

    // ③ 还有漏的 → 逐个 java.ajax（老版本无 ajaxAll）
    var still = 0;
    for (var c = 0; c < hdLinks.length; c++) { if (!hdMap[hdLinks[c]]) still++; }
    if (still > 0 && typeof java.ajax === 'function') {
      mode += '+ajax' + still;
      for (var q = 0; q < hdLinks.length && still > 0; q++) {
        if (hdMap[hdLinks[q]]) continue;
        var one = '';
        try { one = String(java.ajax(withCookie(hdLinks[q]) || '') || ''); } catch (eA) { one = ''; }
        if (!one) { try { one = String(java.ajax(withCookie(hdTry[q]) || '') || ''); } catch (eB) { one = ''; } }
        if (!one) continue;
        var uq = hdPick(one);
        if (uq) { hdMap[hdLinks[q]] = uq; okN++; still--; }
      }
    }

    hdDiag = (mode || 'none') + ' ' + okN + '/' + hdLinks.length +
             ' ck:' + (ckState || '?') +
             (hdSample ? ' {' + hdSample + '}' : '');
  } else {
    hdDiag = '无链接';
  }

  // 剩余待懒加载的链接
  var hdRest = [];
  for (var hr = HD_MAX; hr < thumbs.length; hr++) {
    if (thumbs[hr] && thumbs[hr].link) hdRest.push(thumbs[hr].link);
  }


  // ===== 正文图片流（真机实证重写 261118）=====
  // ★根因：站点 gt200 布局每分页是一张 sprite 拼图（20格共用一张 4336330-N.webp），
  //   parseThumbs 的 .thumb 是 sprite 图 => 344格只有18个唯一URL、每图重复20次 => 看着就是"小图反复"。
  //   ★正解：正文必须用每个 /s/ 链接抓真正的单图大图(<img id=img src=...> 1280x)，绝不用 sprite thumb。
  var cols = gv('ehCols', '1');                 // 行数由登录「正文每行N图」控制：1=一行一个大图 / 2=一行两个
  if (cols !== '2') cols = '1';
  // ★画质(像素)完全由登录面板「分辨率选择」+「⚙同步站点分辨率」写入的账号 xr 决定：
  //   /s/ 页 <img id=img src=...> URL 自带 xres(=780/1280/原图)，书源不再干预像素，也不限制张数。
  //   ★所有页都抓真图（不再用会被重复放大的 sprite），全部 style:FULL 铺满屏宽。
  var total = thumbs.length;
  var take = total;

  // 并发抓 /s/ 页拿真图 URL；表站优先，漏的里站带 Cookie 补。
  // 每批15并发、无 sleep（保正文加载速度）；抓不到的页跳过，不塞 sprite。
  var bigUrls = [];       // 与 thumbs[0..take-1] 对齐；抓不到的位置留 ''
  function fillBatch(idxList, useCookie) {
    var list = [], j;
    for (j = 0; j < idxList.length; j++) {
      var lk = thumbs[idxList[j]].link || '';
      list.push(useCookie ? withCookie(lk) : toPublic(lk));
    }
    var res = null;
    try { res = java.ajaxAll(list, true); } catch (eA) { try { res = java.ajaxAll(list); } catch (eB) {} }
    if (!res) return;
    var n = 0;
    try { n = res.length; } catch (eL) { try { n = res.size(); } catch (eS) {} }
    for (j = 0; j < n && j < idxList.length; j++) {
      var it = null;
      try { it = res[j]; } catch (eG) { try { it = res.get(j); } catch (eH) {} }
      if (!it) continue;
      var b = respBody(it);
      var big = hdPick(b);                 // <img id=img src="...1280...">
      if (big) bigUrls[idxList[j]] = big;
    }
  }
  for (var off = 0; off < take; off += 15) {
    var batch = [];
    for (var q = off; q < take && q < off + 15; q++) batch.push(q);
    fillBatch(batch, false);               // 表站公开 /s/
  }
  // 表站漏的（里站独占画廊）→ 里站带 Cookie 补
  var miss = [];
  for (var m = 0; m < take; m++) if (!bigUrls[m]) miss.push(m);
  for (var mo = 0; mo < miss.length; mo += 10) {
    var mb = [];
    for (var mn = mo; mn < miss.length && mn < mo + 10; mn++) mb.push(miss[mn]);
    fillBatch(mb, true);                   // 里站 /s/ + Cookie
  }

  var got = 0; for (var gi = 0; gi < bigUrls.length; gi++) if (bigUrls[gi]) got++;
  if (!got) {
    return '⚠ 未取到任何大图。请在登录面板确认：①已粘贴自己的 Cookie ②代理可用 ③分辨率档位正确；然后退出重进本书刷新正文缓存。';
  }
  // img 选项只放纯字符串（Map<String,String> 可解析）：一行1图 style:FULL 铺满；一行2图 width:50%
  var Q = String.fromCharCode(34), LB = String.fromCharCode(123);
  var OPT = '';   // ★漫画模式(bookSourceType=2)：flowImages 提取纯 URL，阅读器原生铺满/缩放
  var NLc = String.fromCharCode(10);
  var head = '🖼 画廊图片 · 共 ' + total + ' 页 · 已取 ' + got + '/' + take + ' 张（漫画图片模式；像素=登录面板画质档位）' +
             NLc + '━━━━━━━━━━━━' + NLc;
             NLc + '━━━━━━━━━━━━' + NLc;
  var tail = NLc + NLc + '📖 图片链接带时效签名，隔很久重看若裂图请重新进入刷新；画廊信息/订阅/收藏在本书「详情→简介」面板。';
  var body = [];
  for (var z = 0; z < take; z++) {
    if (!bigUrls[z]) continue;
    var u = String(bigUrls[z]).replace(/&amp;/g, '&').trim();
    body.push('<img src="' + esc(u) + OPT + '">');
  }
  if (take < total) {
    body.push(NLc + '（还有 ' + (total - take) + ' 页未显示：登录面板把分辨率切到「超清·全量」后退出重进可加载全部）');
  }
  return head + body.join(NLc + NLc) + tail;

})()

