@js:(function(){
  function norm(u){
    var s = String(u == null ? '' : u).replace(/&amp;/g, '&').trim();
    s = s.replace(/^https?:\/\/s\.exhentai\.org/i, 'https://ehgt.org');
    s = s.replace(/^https?:\/\/ehgt\.org/i, 'https://ehgt.org');
    return s;
  }
  function ok(u){
    var s = norm(u);
    if (!s || s.indexOf('http') !== 0) return '';
    if (s.indexOf('/g/') > -1) return '';
    if (s.indexOf('ehgt.org/') > -1) return s;
    if (s.indexOf('hath.network') > -1) return s;
    return '';
  }
  try{
    var i = result.select('.glthumb img');
    for (var a = 0; a < i.size(); a++) {
      var v = ok(i.get(a).attr('data-src')) || ok(i.get(a).attr('src'));
      if (v) return v;
    }
    var j = result.select('img');
    for (var b = 0; b < j.size(); b++) {
      var v2 = ok(j.get(b).attr('data-src')) || ok(j.get(b).attr('src'));
      if (v2) return v2;
    }
    var dv = result.select('div');
    for (var c = 0; c < dv.size(); c++) {
      var st = String(dv.get(c).attr('style') || '');
      if (st.indexOf('url(') < 0) continue;
      var mm = st.match(/url\(([^)]+)\)/);
      if (mm) {
        var v3 = ok(String(mm[1]).replace(/["']/g, ''));
        if (v3) return v3;
      }
    }
  }catch(e){}
  return '';
})()

